const fs = require('fs');

function auditSuite(file, minChecks, expectedPrefixes) {
  const code = fs.readFileSync(file, 'utf8');
  // Find all check calls: check('...', '...', ..., () => { ... })
  // Regex to match check calls
  const checkMatches = [...code.matchAll(/check\s*\(\s*(['\"][^'\"]+['\"])\s*,\s*(['\"][^'\"]+['\"])/g)];
  console.log(\`Suite \${file}: found \${checkMatches.length} checks (expected >= \${minChecks})\`);

  if (checkMatches.length < minChecks) {
    console.error(\`ERROR: Suite \${file} has \${checkMatches.length} < \${minChecks} checks!\`);
    process.exit(1);
  }

  // Check for tautological assertions
  const tautologies = [
    'assert(true)',
    'assert.ok(true)',
    'assert.strictEqual(true, true)',
    'assert.strictEqual(1, 1)',
    'assert.equal(1, 1)',
    'assert(1 === 1)',
    'assert(1 == 1)'
  ];
  for (const t of tautologies) {
    if (code.includes(t)) {
      console.warn(\`WARNING: Potential tautological assertion found in \${file}: \${t}\`);
    }
  }

  // Count assertions (assert(...) or assert.something)
  const assertCalls = [...code.matchAll(/assert(\.[a-zA-Z0-9_]+)?\s*\(/g)];
  console.log(\`Suite \${file}: total assert calls = \${assertCalls.length}\`);
  if (assertCalls.length < checkMatches.length) {
    console.warn(\`WARNING: \${file} has fewer assert calls (\${assertCalls.length}) than checks (\${checkMatches.length})\`);
  }
}

